/**
 * Starter template library (50 templates across 5 categories).
 * Pure data: the Template Engine interprets these definitions. New templates —
 * built-in or user-made (stored in the database) — need no engine changes.
 *
 * String placeholders: {{field}}, {{item.title}}, {{item.body}}, {{n}} (1..N),
 * {{rank}} (N..1), {{count}}, {{t:phrase}} (localized phrase), {{a|fallback}}.
 */
import type { LocalizedText, Platform, SceneBlueprint, TemplateCategory, TemplateDefinition, Aspect } from './types';
import type { ProductionMode } from '../planning/types';
import { F } from './fields';

const tx = (en: string, he: string, ru: string, ar: string, am: string): LocalizedText => ({ en, he, ru, ar, am });

type Def = Omit<TemplateDefinition, 'version' | 'platforms' | 'aspects' | 'defaultAspect' | 'modes' | 'recommendedMode' | 'captions'> & {
  platforms?: Platform[]; aspects?: Aspect[]; defaultAspect?: Aspect; modes?: ProductionMode[]; recommendedMode?: ProductionMode;
  captions?: TemplateDefinition['captions'];
};

const SHORT: Platform[] = ['shorts', 'tiktok', 'instagram', 'facebook'];
const LONG: Platform[] = ['youtube', 'facebook'];

function T(d: Def): TemplateDefinition {
  const long = d.category === 'longform';
  return {
    version: 1,
    platforms: d.platforms ?? (long ? LONG : SHORT),
    defaultAspect: d.defaultAspect ?? (long ? '16:9' : '9:16'),
    aspects: d.aspects ?? (long ? ['16:9', '9:16', '1:1'] : ['9:16', '1:1', '4:5', '16:9']),
    modes: d.modes ?? ['code', 'ai', 'hybrid'],
    recommendedMode: d.recommendedMode ?? 'hybrid',
    captions: d.captions ?? { enabled: true },
    ...d,
  } as TemplateDefinition;
}

// Common blueprint snippets
const cta = (label = '{{t:follow}}', headline = '{{cta|t:follow}}'): SceneBlueprint => ({ role: 'cta', layout: 'cta', weight: 0.9, headline, label, kicker: '{{handle}}', narration: '{{cta}}' });
const items = (field = 'items', min = 1, max = 6) => ({ field, min, max });

